import{_ as o,c as t,o as r,aj as l}from"./chunks/framework.D26WZD1w.js";const u=JSON.parse('{"title":"🏥 寒暑假异地就医操作流程","description":"","frontmatter":{"comment":false},"headers":[],"relativePath":"zh-cn/workflows/medical.md","filePath":"zh-cn/workflows/medical.md","lastUpdated":1785552058000}'),i={name:"zh-cn/workflows/medical.md"};function s(n,a,e,h,c,d){return r(),t("div",null,a[0]||(a[0]=[l('<h1 id="🏥-寒暑假异地就医操作流程" tabindex="-1">🏥 寒暑假异地就医操作流程 <a class="header-anchor" href="#🏥-寒暑假异地就医操作流程" aria-label="Permalink to &quot;🏥 寒暑假异地就医操作流程&quot;">​</a></h1><div class="danger custom-block"><p class="custom-block-title">提示</p><p>本流程适用于需要在珠海市以外地区就医的 BNBU 学生。请按照以下步骤完成异地就医备案。</p></div><h2 id="前置步骤" tabindex="-1">前置步骤 <a class="header-anchor" href="#前置步骤" aria-label="Permalink to &quot;前置步骤&quot;">​</a></h2><p>如选择线上操作，可以添加 <strong>BNBU 医疗及健康教育中心</strong> 微信：<strong>a13928025919</strong> 如选择线下操作，请前往 <strong>北师香港浸会大学医务室</strong> 领取资料表格</p><h2 id="第一步-定点" tabindex="-1">第一步：定点 <a class="header-anchor" href="#第一步-定点" aria-label="Permalink to &quot;第一步：定点&quot;">​</a></h2><p>在微信中完成门诊选点登记，将学校医务室设为定点医疗机构</p><h3 id="选点步骤" tabindex="-1">选点步骤 <a class="header-anchor" href="#选点步骤" aria-label="Permalink to &quot;选点步骤&quot;">​</a></h3><ol><li>打开 <strong>微信小程序</strong></li><li>搜索并进入 <strong>珠海社保掌上办</strong></li><li>选择 <strong>医疗生育保险</strong></li><li>点击 <strong>门诊选点登记</strong></li><li>选择 <strong>新增选点</strong></li><li>选择 <strong>门诊统筹选点</strong></li><li>选择区域：<strong>高新技术产业开发区</strong></li><li>选择机构：<strong>北师香港浸会大学医务室</strong></li></ol><h2 id="第二步-领取并填写备案表" tabindex="-1">第二步：领取并填写备案表 <a class="header-anchor" href="#第二步-领取并填写备案表" aria-label="Permalink to &quot;第二步：领取并填写备案表&quot;">​</a></h2><ol><li>线上微信/线下领取 <strong>异地就医备案表</strong></li><li>如实填写表格内容</li><li>将填写好的备案表 <strong>交还医疗及健康教育中心盖章</strong></li></ol><div class="info custom-block"><p class="custom-block-title">注意</p><p>盖章流程通常需要等待3-5个工作日，请耐心等待。盖章完成后，医务室会通知你领取备案表</p></div><h2 id="第三步-异地申请" tabindex="-1">第三步：异地申请 <a class="header-anchor" href="#第三步-异地申请" aria-label="Permalink to &quot;第三步：异地申请&quot;">​</a></h2><p>在微信小程序中完成异地就医备案申请。</p><h3 id="备案步骤" tabindex="-1">备案步骤 <a class="header-anchor" href="#备案步骤" aria-label="Permalink to &quot;备案步骤&quot;">​</a></h3><ol><li>打开 <strong>微信小程序</strong></li><li>搜索并进入 <strong>珠海社保掌上办</strong></li><li>选择 <strong>医疗生育保险</strong></li><li>点击 <strong>异地就医备案</strong></li><li>填写 <strong>电话号码</strong></li><li>选择备案类型：<strong>异地长期居住（含在校大学生）</strong></li><li>填写就医地：<strong>转去的地址</strong>（即你要就医的城市/医院）</li><li>填写参保地：<strong>学校地址</strong></li><li>选择材料类型：<strong>长期居住认定类型</strong></li><li>点击 <strong>下一步</strong></li><li><strong>拍照上传</strong> 第二步中已盖章的异地就医备案表</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>通常来说会在 10 分钟内完成审核</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="q-备案需要多长时间审核通过" tabindex="-1">Q：备案需要多长时间审核通过？ <a class="header-anchor" href="#q-备案需要多长时间审核通过" aria-label="Permalink to &quot;Q：备案需要多长时间审核通过？&quot;">​</a></h3><p>A：一般情况下，提交备案后 1-3 个工作日内可完成审核</p><h3 id="q-为什么需要异地就医备案" tabindex="-1">Q: 为什么需要异地就医备案？ <a class="header-anchor" href="#q-为什么需要异地就医备案" aria-label="Permalink to &quot;Q: 为什么需要异地就医备案？&quot;">​</a></h3><p>中国的<strong>基本医疗保险</strong>实行属地管理，即参保人的医保关系绑定在参保地（珠海）。当你需要在珠海以外的城市就医时，就属于&quot;异地就医&quot;。</p><p>未办理备案的，无法在异地定点医疗机构直接刷医保卡/刷医保码结算，需要<strong>先自费垫付全部医疗费用</strong>，再回到珠海参保地申请手工报销</p><p>未经备案的异地就医，报销比例通常会<strong>大幅降低</strong>，个人负担加重，而且需要自行收集并寄回大量票据、病历等材料，审批周期长</p><h3 id="q-办理备案后的好处" tabindex="-1">Q: 办理备案后的好处 <a class="header-anchor" href="#q-办理备案后的好处" aria-label="Permalink to &quot;Q: 办理备案后的好处&quot;">​</a></h3><ul><li><strong>直接结算</strong>：在异地定点医疗机构刷医保卡/医保码即可完成费用结算，只需支付个人自付部分</li><li><strong>报销比例正常</strong>：执行&quot;就医地目录、参保地政策&quot;，即药品和诊疗项目按就医地规定，报销比例按珠海参保地政策正常执行</li></ul><h3 id="q-使用流程" tabindex="-1">Q: 使用流程 <a class="header-anchor" href="#q-使用流程" aria-label="Permalink to &quot;Q: 使用流程&quot;">​</a></h3><p>打开微信“我的医保凭证”小程序，缴费时候告知并出示二维码；或者出示社保卡</p>',27)]))}const p=o(i,[["render",s]]);export{u as __pageData,p as default};
